package com.example.credservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;

import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.UUID;
import java.util.Base64;
import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;

@SpringBootApplication
@EnableScheduling
@RestController
@RequestMapping("/api/v1")
public class CredentialCacheService {

    // In-memory credential cache - entries are never evicted
    private static final Map<String, CachedCredential> credentialCache = new ConcurrentHashMap<>();

    @Value("${vault.token:hvs.CAESIG5lZGVkX3Rva2VuX2Zvcl92YXVsdA}")
    private String vaultToken;

    @Value("${db.password:prod-db-Xk9#mP2$vL7}")
    private String dbPassword;

    @Value("${aws.secret.key:wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY}")
    private String awsSecretKey;

    static class CachedCredential {
        String sessionId;
        String username;
        String rawToken;
        String derivedSecret;
        long timestamp;
        byte[] padding; // Simulates associated session data

        CachedCredential(String sessionId, String username, String rawToken) {
            this.sessionId = sessionId;
            this.username = username;
            this.rawToken = rawToken;
            this.derivedSecret = Base64.getEncoder().encodeToString(
                (rawToken + System.currentTimeMillis()).getBytes());
            this.timestamp = System.currentTimeMillis();
            this.padding = new byte[4096]; // 4KB per entry
        }
    }

    @PostMapping("/authenticate")
    public Map<String, String> authenticate(@RequestBody Map<String, String> request) {
        String username = request.get("username");
        String password = request.get("password");

        // Simplified auth - in production would validate against IdP
        String sessionId = UUID.randomUUID().toString();
        String token = generateToken(username);

        // VULNERABILITY: credentials cached indefinitely, never evicted
        CachedCredential cred = new CachedCredential(sessionId, username, token);
        credentialCache.put(sessionId, cred);

        return Map.of("session_id", sessionId, "token", token);
    }

    @GetMapping("/session/{sessionId}")
    public Map<String, Object> getSession(@PathVariable String sessionId) {
        CachedCredential cred = credentialCache.get(sessionId);
        if (cred == null) {
            return Map.of("error", "session not found");
        }
        // Exposes raw token in response
        return Map.of(
            "username", cred.username,
            "token", cred.rawToken,
            "derived_secret", cred.derivedSecret,
            "created", cred.timestamp
        );
    }

    @GetMapping("/debug/heap")
    public Map<String, Object> heapDump() throws Exception {
        // Exposes heap information including credential count
        MemoryMXBean memBean = ManagementFactory.getMemoryMXBean();
        Runtime rt = Runtime.getRuntime();

        return Map.of(
            "heap_used", memBean.getHeapMemoryUsage().getUsed(),
            "heap_max", memBean.getHeapMemoryUsage().getMax(),
            "cached_credentials", credentialCache.size(),
            "free_memory", rt.freeMemory(),
            "vault_token_prefix", vaultToken.substring(0, 8) + "..."
        );
    }

    @GetMapping("/debug/dump")
    public String dumpCredentials() {
        // Full credential dump endpoint - should be admin-only
        StringBuilder sb = new StringBuilder();
        credentialCache.forEach((k, v) -> {
            sb.append(String.format("Session: %s | User: %s | Token: %s | Secret: %s\n",
                k, v.username, v.rawToken, v.derivedSecret));
        });
        return sb.toString();
    }

    @PostMapping("/debug/gc")
    public Map<String, String> forceGC() {
        // Attempt GC but cached creds remain as strong references
        System.gc();
        return Map.of("status", "gc_requested", "remaining_entries", 
            String.valueOf(credentialCache.size()));
    }

    private String generateToken(String username) {
        // Embeds service credentials in user token (bad practice)
        String payload = username + ":" + dbPassword + ":" + System.currentTimeMillis();
        return Base64.getEncoder().encodeToString(payload.getBytes());
    }

    @Scheduled(fixedRate = 60000)
    public void reportMetrics() {
        // Logs credential cache size but never cleans up
        System.out.printf("[METRICS] Cache size: %d, Heap: %d MB%n",
            credentialCache.size(),
            Runtime.getRuntime().totalMemory() / (1024 * 1024));
    }

    public static void main(String[] args) {
        SpringApplication.run(CredentialCacheService.class, args);
    }
}
